import PageShell from "../../components/PageShell.jsx";

const services = [
  ["01", "Websites that work", "Distinctive, responsive websites built to turn visitors into customers."],
  ["02", "E-commerce, made easy", "A smoother way to sell online, from product pages to checkout."],
  ["03", "Apps for what’s next", "Useful mobile experiences that bring your services closer to customers."],
  ["04", "The tools behind it all", "Custom dashboards, APIs and business systems for the way your team works."],
];

export default function ServicesPage() {
  return (
    <PageShell>
      <section className="section-pad" aria-labelledby="services-heading">
        <p className="section-label">WHAT WE DO</p>
        <h1 id="services-heading">Digital, with<br /><em>a human touch.</em></h1>
        <div className="service-grid">
          {services.map(([number, title, description]) => <article className="service-card" key={number}><div className="service-top"><span>{number} / 04</span></div><h2>{title}</h2><p>{description}</p></article>)}
        </div>
      </section>
    </PageShell>
  );
}